-- BUG: stray closing tag </Session.closeRq> with no matching opener, hardcoded in the boilerplate
-- tail of PER_CONVERSION_FINAL_XML's template literal. Should be self-closing: <Session.closeRq/>
--
-- Found 2026-07-14 via the new PP XML Field Validator (Streamlit page) -- looked up policy
-- P00000217 in DEV, got "XML parse error: mismatched tag: line 508, column 10" on the real
-- generated REQUEST_XML. Confirmed live:
--   - AGGNE.DEV.PER_CONVERSION_FINAL_XML() has the buggy literal '</Session.closeRq>' baked in
--     (1 occurrence) -- affects every policy generated by this procedure, i.e. all of DEV's
--     current REQUEST_XML population.
--   - AGGNE.UAT.PER_CONVERSION_FINAL_XML() has the SAME buggy literal in its definition.
--   - BUT UAT's already-stored REQUEST_XML rows show the CORRECT '<Session.closeRq/>' -- meaning
--     UAT's stored data predates this bug being introduced into the procedure (a frozen
--     snapshot from an earlier, correct version), NOT evidence the bug is fixed. If UAT's
--     PER_CONVERSION_FINAL_XML is ever called again as-is, it will produce the same malformed
--     XML DEV has now.
--
-- This is very likely the real root cause of the unexplained "mismatched tag" DCT submission
-- failure mentioned earlier this week (all 46 UAT policies failed once with this exact error
-- signature, root cause never disclosed/diagnosed at the time, then a batch re-run succeeded --
-- almost certainly because that re-run read from UAT's still-pre-bug REQUEST_XML rows, not
-- because the underlying SP bug was actually fixed).
--
-- Fix: change '</Session.closeRq>' to '<Session.closeRq/>' -- single line, no other changes.
-- Full procedure body re-pulled fresh via GET_DDL this session (both DEV and UAT), dry-run
-- tested with a Python string replace against the live text first (1 occurrence, confirmed)
-- before writing this file -- same discipline as every other SP edit this session.
--
-- IMPORTANT: after deploying this, DEV's PER_POLICY_MIGRATION_DCT needs a fresh
-- PER_CONVERSION_FINAL_XML() run (or a full PP_CONVERSION_RUN(TRUE) reload) to actually pick up
-- the fix in stored data -- the existing DEV rows are still malformed until regenerated.
-- UAT does NOT need an immediate reload (its current rows are already correct, coincidentally) --
-- but MUST get this fix before its next real reload, or the same failure will recur.

-- =====================================================================
-- DEV
-- =====================================================================
CREATE OR REPLACE PROCEDURE "PER_CONVERSION_FINAL_XML"()
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS 'BEGIN

insert into AGGNE.DEV.PER_POLICY_MIGRATION_DCT_PREVDATA
select *,getdate() as LoadDate from AGGNE.DEV.PER_POLICY_MIGRATION_DCT;

TRUNCATE TABLE  AGGNE.DEV.PER_POLICY_MIGRATION_DCT;

INSERT INTO AGGNE.DEV.PER_POLICY_MIGRATION_DCT (CML_NUMBER,BUCKET,LEGACYPOLICYNUMBER,REQUEST_XML)
        SELECT DISTINCT CMLNUMBER, NTILE(10) OVER (ORDER BY LEGACYPOLICYNUMBER) BUCKET, LEGACYPOLICYNUMBER, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(''<server>
	<requests>
