							<CSLNumber>{CSLNUMBER}</CSLNumber>
							<CurrentCSL>{CSLNUMBER}</CurrentCSL>
							<CSLLegalEntityName>{CSL_LEGAL_ENTITY}</CSLLegalEntityName>
